import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel b8bd735:
# packet.UpdateEquip{WindowID: 1, WindowType: 12, Size: 2, EntityUniqueID: 7,
# SerialisedInventoryData: nbt.MarshalEncoding(map[string]any{"Size": int32(2)}, nbt.NetworkLittleEndian)}
HORSE = bytes.fromhex("010c040e0a00030453697a650400")

# generated by gophertunnel b8bd735:
# packet.UpdateEquip{WindowID: 0xff, WindowType: 0xf7, Size: 300, EntityUniqueID: -1,
# SerialisedInventoryData: nbt.MarshalEncoding(map[string]any{}, nbt.NetworkLittleEndian)}
NONE = bytes.fromhex("fff7d804010a0000")

GOLDENS = [
    pytest.param(
        v2168.UpdateEquipPacket(
            container_id=v2168.ContainerID.FIRST,
            type=v2168.ContainerType.HORSE,
            size=2,
            entity_unique_id=7,
            data=v2168.nbt.CompoundTag({"Size": v2168.nbt.IntTag(2)}),
        ),
        HORSE,
        id="horse",
    ),
    pytest.param(
        v2168.UpdateEquipPacket(
            container_id=v2168.ContainerID.NONE,
            type=v2168.ContainerType.NONE,
            size=300,
            entity_unique_id=-1,
        ),
        NONE,
        id="sentinels",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_update_equip_is_packet_81(version):
    assert version.PACKETS[81] is version.UpdateEquipPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_equip_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_equip_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
